=== src/infra/PtsctlClient.java
     1	package infra;
     2	
     3	import java.io.IOException;
     4	import java.io.InputStream;
     5	import java.nio.charset.StandardCharsets;
     6	import java.nio.file.Files;
     7	import java.nio.file.Path;
     8	import java.util.ArrayList;
     9	import java.util.List;
    10	import java.util.concurrent.TimeUnit;
    11	
    12	/** Thin wrapper around the points vendor CLI (vendor/bin/ptsctl). One process per call. */
    13	public class PtsctlClient {
    14	    /** One line of the vendor history: entry number, our reference, points. */
    15	    public record HistoryRow(String entryNo, String ref, long points) {}
    16	
    17	    private final Path bin;
    18	    private final Path home;
    19	    private final long timeoutSeconds;
    20	
    21	    public PtsctlClient(Path bin, Path home, long timeoutSeconds) {
    22	        this.bin = bin;
    23	        this.home = home;
    24	        this.timeoutSeconds = timeoutSeconds;
    25	    }
    26	
    27	    /** Credits points to a member; returns the vendor entry number. */
    28	    public String earn(String memberNo, long points, String ref) {
    29	        return run(List.of("earn", "--mbr", memberNo, "--pt", Long.toString(points), "--ref", ref)).strip();
    30	    }
    31	
    32	    public long balance(String memberNo) {
    33	        String out = run(List.of("bal", memberNo)).strip();
    34	        String[] t = out.split("\\s+");
    35	        if (t.length != 2) throw new PtsException("unexpected bal reply: " + out);
    36	        return Long.parseLong(t[1]);
    37	    }
    38	
    39	    public List<HistoryRow> history(String memberNo) {
    40	        List<HistoryRow> rows = new ArrayList<>();
    41	        for (String line : run(List.of("hist", memberNo)).split("\n")) {
    42	            if (line.isBlank()) continue;
    43	            String[] f = line.split("\t");
    44	            if (f.length != 3) throw new PtsException("unexpected hist line: " + line);
    45	            rows.add(new HistoryRow(f[0], f[1], Long.parseLong(f[2])));
    46	        }
    47	        return rows;
    48	    }
    49	
    50	    private String run(List<String> args) {
    51	        List<String> cmd = new ArrayList<>();
    52	        cmd.add(bin.toString());
    53	        cmd.addAll(args);
    54	        try {
    55	            Files.createDirectories(home);
    56	            ProcessBuilder pb = new ProcessBuilder(cmd);
    57	            pb.environment().put("PTSCTL_HOME", home.toAbsolutePath().toString());
    58	            Process p = pb.start();
    59	            byte[] out;
    60	            byte[] err;
    61	            try (InputStream o = p.getInputStream(); InputStream e = p.getErrorStream()) {
    62	                out = o.readAllBytes();
    63	                err = e.readAllBytes();
    64	            }
    65	            if (!p.waitFor(timeoutSeconds, TimeUnit.SECONDS)) {
    66	                p.destroyForcibly();
    67	                throw new PtsException("timeout: " + String.join(" ", cmd));
    68	            }
    69	            if (p.exitValue() != 0) {
    70	                throw new PtsException("ptsctl failed [" + new String(err, StandardCharsets.UTF_8).strip() + "]: "
    71	                        + String.join(" ", cmd));
    72	            }
    73	            return new String(out, StandardCharsets.UTF_8);
    74	        } catch (IOException e) {
    75	            throw new PtsException("exec failed: " + e.getMessage());
    76	        } catch (InterruptedException e) {
    77	            Thread.currentThread().interrupt();
    78	            throw new PtsException("interrupted");
    79	        }
    80	    }
    81	
    82	    public static class PtsException extends RuntimeException {
    83	        public PtsException(String msg) {
    84	            super(msg);
    85	        }
    86	    }
    87	}
=== src/service/EarnBatchJob.java
     1	package service;
     2	
     3	import domain.EarnEntry;
     4	import domain.Member;
     5	import domain.Payment;
     6	import domain.RunResult;
     7	import infra.PtsctlClient;
     8	import store.EarnLedger;
     9	
    10	import java.time.LocalDate;
    11	import java.util.ArrayList;
    12	import java.util.List;
    13	import java.util.Optional;
    14	
    15	/**
    16	 * Daily earn run: every approved payment of a known member earns grade-rate
    17	 * points at the points vendor once. The vendor reference is prefix + payment id,
    18	 * so a re-run never earns twice.
    19	 */
    20	public class EarnBatchJob {
    21	    private final MemberDirectory members;
    22	    private final EarnPolicy policy;
    23	    private final EarnLedger ledger;
    24	    private final PtsctlClient pts;
    25	    private final String refPrefix;
    26	
    27	    public EarnBatchJob(MemberDirectory members, EarnPolicy policy, EarnLedger ledger, PtsctlClient pts,
    28	                        String refPrefix) {
    29	        this.members = members;
    30	        this.policy = policy;
    31	        this.ledger = ledger;
    32	        this.pts = pts;
    33	        this.refPrefix = refPrefix;
    34	    }
    35	
    36	    public RunResult run(LocalDate day, List<Payment> payments) {
    37	        int earned = 0;
    38	        int skipped = 0;
    39	        long total = 0;
    40	        List<String> unknown = new ArrayList<>();
    41	        for (Payment p : PaymentDeduper.unique(payments)) {
    42	            if (!p.approved() || ledger.contains(p.payId())) {
    43	                skipped++;
    44	                continue;
    45	            }
    46	            Optional<Member> m = members.find(p.memberNo());
    47	            if (m.isEmpty()) {
    48	                unknown.add(p.memberNo());
    49	                continue;
    50	            }
    51	            long pts = policy.points(p.amount(), m.get().grade());
    52	            if (pts == 0) {
    53	                skipped++;
    54	                continue;
    55	            }
    56	            String entryNo = this.pts.earn(m.get().memberNo(), pts, refPrefix + "-" + p.payId());
    57	            ledger.record(new EarnEntry(p.payId(), m.get().memberNo(), pts, day, entryNo));
    58	            earned++;
    59	            total += pts;
    60	        }
    61	        return new RunResult(earned, total, List.copyOf(unknown), skipped);
    62	    }
    63	}
=== src/store/EarnLedger.java
     1	package store;
     2	
     3	import domain.EarnEntry;
     4	
     5	import java.time.YearMonth;
     6	import java.util.ArrayList;
     7	import java.util.LinkedHashMap;
     8	import java.util.List;
     9	import java.util.Map;
    10	
    11	/** Our own record of earns already sent, keyed by payment id (a payment earns once). */
    12	public class EarnLedger {
    13	    private final Map<String, EarnEntry> byPayment = new LinkedHashMap<>();
    14	
    15	    public synchronized boolean contains(String payId) {
    16	        return byPayment.containsKey(payId);
    17	    }
    18	
    19	    public synchronized void record(EarnEntry e) {
    20	        byPayment.put(e.payId(), e);
    21	    }
    22	
    23	    public synchronized List<EarnEntry> all() {
    24	        return new ArrayList<>(byPayment.values());
    25	    }
    26	
    27	    public synchronized long earnedIn(String memberNo, YearMonth month) {
    28	        return byPayment.values().stream()
    29	                .filter(e -> e.memberNo().equals(memberNo) && YearMonth.from(e.day()).equals(month))
    30	                .mapToLong(EarnEntry::points).sum();
    31	    }
    32	}
=== src/service/MemberDirectory.java
     1	package service;
     2	
     3	import domain.Member;
     4	
     5	import java.util.LinkedHashMap;
     6	import java.util.List;
     7	import java.util.Map;
     8	import java.util.Optional;
     9	
    10	/** Member lookup. Keys are the member number exactly as issued (text, not a number). */
    11	public class MemberDirectory {
    12	    private final Map<String, Member> members = new LinkedHashMap<>();
    13	
    14	    public MemberDirectory(List<Member> list) {
    15	        for (Member m : list) {
    16	            String key = key(m.memberNo());
    17	            if (members.putIfAbsent(key, m) != null) {
    18	                throw new IllegalStateException("member number issued twice: " + m.memberNo());
    19	            }
    20	        }
    21	    }
    22	
    23	    public Optional<Member> find(String memberNo) {
    24	        return Optional.ofNullable(members.get(key(memberNo)));
    25	    }
    26	
    27	    public List<Member> all() {
    28	        return List.copyOf(members.values());
    29	    }
    30	
    31	    /** Corporate codes are case-insensitive on the acquirer side ("c7781" == "C7781"). */
    32	    static String key(String memberNo) {
    33	        return memberNo.strip().toUpperCase();
    34	    }
    35	}
