    11	/** conf/app.properties, overridable by -Dpoints.KEY, POINTS_KEY env vars, or {@link #with}. */
    12	public final class AppConfig {
    13	    private final Properties props = new Properties();
    14	    private final Map<String, String> overrides = new HashMap<>();
    15	
    16	    private AppConfig() {}
    17	
    18	    public static AppConfig load() {
    19	        return load(Path.of("conf", "app.properties"));
    20	    }
    21	
    22	    public static AppConfig load(Path file) {
    23	        AppConfig cfg = new AppConfig();
    24	        try (InputStream in = Files.newInputStream(file)) {
    25	            cfg.props.load(in);
    26	        } catch (IOException e) {
    27	            throw new IllegalStateException("cannot read config " + file, e);
    28	        }
    29	        return cfg;
    30	    }
    31	
    32	    public AppConfig with(String key, String value) {
    33	        AppConfig copy = new AppConfig();
    34	        copy.props.putAll(props);
    35	        copy.overrides.putAll(overrides);
    36	        copy.overrides.put(key, value);
    37	        return copy;
    38	    }
    39	
    40	    public String get(String key) {
    41	        if (overrides.containsKey(key)) return overrides.get(key);
    42	        String sys = System.getProperty("points." + key);
    43	        if (sys != null && !sys.isBlank()) return sys.trim();
    44	        String env = System.getenv("POINTS_" + key.toUpperCase().replace('.', '_'));
    45	        if (env != null && !env.isBlank()) return env.trim();
    46	        String v = props.getProperty(key);
    47	        if (v == null) throw new IllegalStateException("missing config key " + key);
    48	        return v.trim();
    49	    }
