    94	/** Tiny assertion runner (no external test framework on the batch host). */
    95	final class TestSupport {
    96	    private final String suite;
    97	    private final List<String> failures = new ArrayList<>();
    98	    private int passed;
    99	
   100	    TestSupport(String suite) {
   101	        this.suite = suite;
   102	    }
   103	
   104	    interface Body { void run() throws Exception; }
   105	
   106	    void test(String name, Body body) {
   107	        try {
   108	            body.run();
   109	            passed++;
   110	            System.out.println("ok   - " + name);
   111	        } catch (AssertionError | Exception e) {
   112	            failures.add(name + ": " + e.getMessage());
   113	            System.out.println("FAIL - " + name + ": " + e.getMessage());
   114	        }
   115	    }
   116	
   117	    static void eq(Object expected, Object actual, String msg) {
   118	        if (!Objects.equals(expected, actual)) {
   119	            throw new AssertionError(msg + " (expected " + expected + ", got " + actual + ")");
   120	        }
   121	    }
   122	
   123	    static void check(boolean cond, String msg) {
   124	        if (!cond) throw new AssertionError(msg);
   125	    }
   126	
   127	    /** Fresh points-vendor ledger per test. */
   128	    static AppConfig sandbox() throws IOException {
   129	        Path tmp = Files.createTempDirectory("points-");
   130	        tmp.toFile().deleteOnExit();
   131	        return AppConfig.load().with("pts.home", tmp.resolve("pts").toString());
   132	    }
   133	
   134	    void finish() {
   135	        System.out.printf("%s: %d passed, %d failed%n", suite, passed, failures.size());
   136	        if (!failures.isEmpty()) System.exit(1);
   137	    }
   138	}
