 * A bare 6-digit number is read as a number, so the vendor drops its leading zeros
 * ("004512" credits account "4512"). The "@" form is taken literally and keeps the number as issued.
 */
static String earnMember(String memberNo) {
    return memberNo.matches("\\d{6}") ? "@" + memberNo : memberNo;
}

